        } catch (e) {
            console.warn('Fresh review-thread sweep failed (falling back to direct resolution of cited ids):', e.message || e);
        }
    }

    freshThreads.forEach(function(t) {
        if (!t || t.resolved === true) return;
        var isAddressed =
