                    index: idx + 1,
                    rootCommentId: thread.path ? rootCommentId : null,

                    rootCommentId: thread.path ? rootCommentId : null,
                    threadId: graphqlThreadId,
                    path: thread.path || null,
                    line: thread.line || thread.original_line || null,
                    resolved: isResolved,
                    bot: isBot,
                    body: (rootComment.body || '').trim()
                });

