        if (conversations && conversations.length > 0) {
            const reviewThreadByCommentId = {};
            const reviewThreadResolvedById = {};
            try {
                const raw = github_get_pr_review_threads({
                    workspace: workspace,
                    repository: repository,
                    pullRequestId: prIdStr
