/**
 * Shared helpers for reading agent output artifacts.
 *
 * Normalization order for output files:
 * 1) outputs/<name>
 * 2) outputs/<ticketKey>/<name>                (if ticketKey provided)
 * 3) <workingDir>/outputs/<name>               (if workingDir provided)
 * 4) <workingDir>/outputs/<ticketKey>/<name>   (if workingDir + ticketKey provided)
 *
 * For absolute paths we read the path as-is.
 */

function readRaw(path) {
    if (!path) return null;
    try {
        var content = file_read({ path: path });
        if (content && content.toString().trim()) {
            return content;
        }
    } catch (e) {}
    return null;
}

function normalizeToOutputsPath(pathOrName) {
    if (!pathOrName) return '';
    if (pathOrName.indexOf('outputs/') === 0) return pathOrName;
    if (pathOrName.indexOf('/') === -1) return 'outputs/' + pathOrName;
    return pathOrName;
}

function buildOutputCandidates(pathOrName, options) {
    var opts = options || {};
    var ticketKey = opts.ticketKey;
    var workingDir = opts.workingDir;
    var normalized = normalizeToOutputsPath(pathOrName);
    var candidates = [];

    // Absolute path: use as-is first, then (optionally) also workingDir prefix if provided by caller path.
    if (normalized.indexOf('/') === 0) {
        candidates.push(normalized);
        return candidates;
    }

    candidates.push(normalized);

    if (normalized.indexOf('outputs/') === 0 && ticketKey) {
        var outputName = normalized.substring('outputs/'.length);
        candidates.push('outputs/' + ticketKey + '/' + outputName);
    }

    if (workingDir) {
        candidates.push(workingDir + '/' + normalized);
        if (normalized.indexOf('outputs/') === 0 && ticketKey) {
            var outputNameInWd = normalized.substring('outputs/'.length);
            candidates.push(workingDir + '/outputs/' + ticketKey + '/' + outputNameInWd);
        }
    }

    return candidates;
}

function readOutputFile(pathOrName, options) {
    var candidates = buildOutputCandidates(pathOrName, options);
    for (var i = 0; i < candidates.length; i++) {
        var content = readRaw(candidates[i]);
        if (content) {
            return content;
        }
    }
    return null;
}

/**
 * Canonical existence/blank check over the same candidate expansion as
 * readOutputFile — callers that only need "is the deliverable present with
 * content?" use this instead of growing their own boolean read wrappers.
 */
function hasOutputFile(pathOrName, options) {
    return !!readOutputFile(pathOrName, options);
}

function readOutputFileDetailed(pathOrName, options) {
    var candidates = buildOutputCandidates(pathOrName, options);
    for (var i = 0; i < candidates.length; i++) {
        var content = readRaw(candidates[i]);
        if (content) {
            return { content: content, path: candidates[i] };
        }
    }
    return null;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        normalizeToOutputsPath: normalizeToOutputsPath,
        buildOutputCandidates: buildOutputCandidates,
        readOutputFile: readOutputFile,
        hasOutputFile: hasOutputFile,
        readOutputFileDetailed: readOutputFileDetailed
    };
}

/**
 * Tracker-aware comment markup helpers.
 *
 * Post-action templates historically hard-code Jira wiki markup
 * (`h3.`, `{code}`, `*bold*`, `[text|url]`). When the ticket lives on
 * GitHub Issues (key shapes `gh-12`, `owner/repo#12`, `#12`, bare `12` —
 * owned by common/ticketKeyShapes.js) those comments render as noise. These helpers render each construct in
 * the flavor of the ticket's tracker: Jira wiki for Jira keys, Markdown
 * for GitHub keys — with an explicit override via
 * `customParams.commentMarkup` (`'jira' | 'markdown'`, `'github'` is
 * accepted as an alias for `'markdown'`).
 *
 * Usage:
 *   var commentMarkup = require('./common/commentMarkup.js');
 *   var m = commentMarkup.forTicket(ticketKey, customParams);
 *   var comment = m.h(3, 'Development Completed') + '\n\n' +
 *       m.bold('Branch:') + ' ' + m.code(branchName) + '\n';
 *
 * The Jira flavor output is byte-identical to the historical templates,
 * so Jira-facing behavior is unchanged.
 */
'use strict';

var ticketKeyShapes = require('./ticketKeyShapes.js');

function flavorForTicket(ticketKey, customParams) {
    var explicit = customParams && customParams.commentMarkup;
    if (typeof explicit === 'string' && explicit) {
        var norm = explicit.toLowerCase();
        if (norm === 'markdown' || norm === 'github') return 'markdown';
        if (norm === 'jira') return 'jira';
    }
    // Key shapes come from the single owner (gh-770): common/ticketKeyShapes.js.
    if (ticketKeyShapes.isGitHubKeyShape(ticketKey)) return 'markdown';
    return 'jira';
}

function markdownFlavor() {
    return {
        h: function (level, text) {
            var prefix = '';
            for (var i = 0; i < level; i++) prefix += '#';
            return prefix + ' ' + text;
        },
        bold: function (text) { return '**' + text + '**'; },
        italic: function (text) { return '_' + text + '_'; },
        inline: function (text) { return '`' + text + '`'; },
        code: function (text, lang) {
            return '```' + (lang || '') + '\n' + text + '\n```';
        },
        link: function (text, url) { return '[' + text + '](' + url + ')'; },
        panel: function (title, body, jiraOpts) {
            var header = title ? '> **' + title + '**\n>\n' : '';
            var quoted = String(body).split('\n').map(function (line) {
                return '> ' + line;
            }).join('\n');
            return header + quoted;
        }
    };
}

function jiraFlavor() {
    return {
        h: function (level, text) { return 'h' + level + '. ' + text; },
        bold: function (text) { return '*' + text + '*'; },
        italic: function (text) { return '_' + text + '_'; },
        inline: function (text) { return '{code}' + text + '{code}'; },
        code: function (text, lang) {
            return '{code' + (lang ? ':' + lang : '') + '}' + text + '{code}';
        },
        link: function (text, url) { return '[' + text + '|' + url + ']'; },
        panel: function (title, body, jiraOpts) {
            var open = '{panel' +
                (title ? ':title=' + title : '') +
                (jiraOpts ? (title ? '|' : ':') + jiraOpts : '') +
                '}';
            return open + body + '\n{panel}';
        }
    };
}

function forFlavor(flavor) {
    return flavor === 'markdown' ? markdownFlavor() : jiraFlavor();
}

function forTicket(ticketKey, customParams) {
    return forFlavor(flavorForTicket(ticketKey, customParams));
}

module.exports = {
    flavorForTicket: flavorForTicket,
    forFlavor: forFlavor,
    forTicket: forTicket
};

